- `D:\Trade-Initial\tests\test_weeklyanchoredvwapreclaim_h041_v1.py`

The 48-bar cap and the one-position rule need state, so a bar-by-bar tracker in `populate_indicators` handles them. It only looks at past rows. It uses the signal bar''s close as a stand-in for the entry price when checking for the 3% stop. The real entry fills at the next open, so the tracker''s idea of when a position has ended can differ slightly from Freqtrade''s.

I left out `protections`, since the proposal asks for no cooldown.','2026-11-06T13:31:29.610438+00:00');
CREATE TABLE approvals (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    hypothesis_id TEXT NOT NULL REFERENCES hypotheses(id),
    stage TEXT NOT NULL,                 -- validation | dryrun
    approved_by TEXT NOT NULL,
    note TEXT NOT NULL DEFAULT '',
    created_at_utc TEXT NOT NULL,
    UNIQUE(hypothesis_id, stage)
);
CREATE TABLE archived_strategies (
    hypothesis_id TEXT PRIMARY KEY REFERENCES hypotheses(id),
    strategy_class TEXT NOT NULL,
    original_path TEXT NOT NULL,
    archive_path TEXT NOT NULL,
    strategy_sha256 TEXT NOT NULL,
    sha256_source TEXT NOT NULL,         -- manifest | experiment | file_at_archive_time
    archived_at_utc TEXT NOT NULL
);
CREATE TABLE decisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    experiment_id TEXT NOT NULL REFERENCES experiments(id),
    decision TEXT NOT NULL,              -- rejected | inconclusive | candidate_for_forward_test
    reasons_json TEXT NOT NULL,
    gates_sha256 TEXT NOT NULL,
    decided_at_utc TEXT NOT NULL
);
CREATE TABLE experiments (
    id TEXT PRIMARY KEY,                 -- experiment id, e.g. "2026-10-27-donchian-h002-explore"
    hypothesis_id TEXT NOT NULL REFERENCES hypotheses(id),
    strategy_file TEXT NOT NULL,
    strategy_sha256 TEXT NOT NULL,
    cost_scenario TEXT NOT NULL,         -- optimistic | base | conservative | stress
    split TEXT NOT NULL,                 -- exploration | validation | final_test
    command TEXT NOT NULL,               -- exact argv, space-joined, for the record
    artifact_path TEXT,
    status TEXT NOT NULL,                -- pending | running | completed | failed
    created_at_utc TEXT NOT NULL
, pair TEXT NOT NULL DEFAULT 'BTC/USDT');
CREATE TABLE hypotheses (
    id TEXT PRIMARY KEY,                 -- e.g. "H-004"
    family TEXT NOT NULL,
    ex_ante_rule TEXT NOT NULL,
    proposed_at_utc TEXT NOT NULL,
    data_visible_at_proposal TEXT NOT NULL,  -- what data window was visible when the rule was fixed
    status TEXT NOT NULL,                -- e.g. "proposed", "frozen reference", "candidate", "rejected"
    notes TEXT
);
CREATE TABLE ideas (
    id TEXT PRIMARY KEY,                 -- e.g. "I-001"
    run_id TEXT NOT NULL,                -- the scout call that produced it
    title TEXT NOT NULL,
    source_type TEXT NOT NULL,           -- paper | blog | repo
    source_url TEXT NOT NULL,
    source_title TEXT NOT NULL,
    license TEXT NOT NULL,               -- of the source, kept for attribution; the rule is reimplemented from scratch
    rule_summary TEXT NOT NULL,
    mechanism TEXT NOT NULL,
    timeframe TEXT NOT NULL,
    longest_lookback INTEGER NOT NULL,   -- in bars of `timeframe`
    free_parameters INTEGER NOT NULL,
    fixed_parameters INTEGER NOT NULL,   -- 1 when the numbers are textbook values fixed before any test
    expected_trades_per_year REAL NOT NULL,  -- the scout's design estimate per pair, NOT a result
    family_hint TEXT NOT NULL,
    rule_hash TEXT NOT NULL,
    state TEXT NOT NULL,                 -- new | queued | dropped | registered
    state_reason TEXT NOT NULL DEFAULT '',
    score REAL,
    hypothesis_id TEXT REFERENCES hypotheses(id),
    created_at_utc TEXT NOT NULL
);
CREATE TABLE metrics (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    experiment_id TEXT NOT NULL REFERENCES experiments(id),
    name TEXT NOT NULL,
    value REAL,
    text_value TEXT,                     -- for non-numeric metrics (e.g. has_bias, notes)
    UNIQUE(experiment_id, name)
);
DELETE FROM "sqlite_sequence";
COMMIT;
